<script setup>
import {ref,onMounted} from 'vue';
import {X,Trash2,RotateCcw,FolderOpen,RefreshCw,LoaderCircle} from 'lucide-vue-next';
import {useStudio,api} from '../store';
const props=defineProps({initial:{type:String,default:'projects'},clearOnOpen:Boolean}),emit=defineEmits(['close','changed']);
const s=useStudio(),tab=ref(props.initial),data=ref({projects:[],images:[]}),busy=ref(false),confirmation=ref(null),error=ref('');
async function refresh(){data.value=await api('trash');}
async function restoreAll(items){
 if(busy.value)return;busy.value=true;error.value='';
 try{await window.__mogeFlush?.();if(tab.value==='projects'){for(const item of items){const result=await api('projects/restore',{id:item.id});s.projects=result.projects;if(result.config)s.config=result.config;}}else if(items.length){for(let offset=0;offset<items.length;offset+=1000)await api('gallery/restore',{ids:items.slice(offset,offset+1000).map(item=>item.id)});}
  await s.refreshCollections();await refresh();emit('changed');s.notify(s.t('已恢复所选内容','Selected content restored'));
 }catch(e){error.value=e.message;}finally{busy.value=false;}
}
function requestPurge(item){confirmation.value=item?{projectIds:tab.value==='projects'?[item.id]:[],imageIds:tab.value==='images'?[item.id]:(item.imageIds||[]).filter(id=>data.value.images.some(image=>image.id===id))}:{projectIds:data.value.projects.map(item=>item.id),imageIds:data.value.images.map(item=>item.id)};}
async function purge(){
 if(busy.value||!confirmation.value)return;busy.value=true;error.value='';
 try{await window.__mogeFlush?.();const result=await api('trash/purge',{...confirmation.value,confirmed:true});confirmation.value=null;data.value={projects:result.projects,images:result.images};emit('changed');s.notify(result.retainedImages?s.t('清理完成；仍被项目使用的图片已保留','Cleanup finished. Images still used by projects were kept'):s.t('回收区垃圾已永久清除','Recycled content permanently deleted'));
 }catch(e){error.value=e.message;}finally{busy.value=false;}
}
onMounted(async()=>{try{await refresh();if(props.clearOnOpen&&(data.value.projects.length||data.value.images.length))requestPurge();}catch(e){error.value=e.message;}});
</script>
<template><div class="modal-backdrop" @click.self="!busy&&emit('close')"><section class="modal recycle-bin" role="dialog" :aria-label="s.t('本地回收区','Local recycle bin')"><div class="modal-dismiss-row"><button class="icon-button" :disabled="busy" :aria-label="s.t('关闭回收区','Close recycle bin')" @click="emit('close')"><X :size="20"/></button></div><div class="modal-title"><h2>{{s.t('本地回收区','Local recycle bin')}}</h2></div><p class="muted">{{s.t('保存在软件目录的 works/trash 中，不属于 Windows 回收站，不会被缓存清理或自动删除。图片原文件会保留到永久删除时，供项目继续使用。','Stored locally in works/trash. This is separate from the Windows Recycle Bin and is never cleared automatically or by cache cleanup. Image files are kept until permanent deletion so projects can keep using them.')}}</p><div class="button-row"><button class="quiet" :disabled="busy" @click="s.action(()=>s.openFolder('trash'))"><FolderOpen :size="15"/>{{s.t('打开回收文件夹','Open recycle folder')}}</button><button class="quiet" :disabled="busy" @click="s.action(refresh)"><RefreshCw :size="15"/>{{s.t('刷新','Refresh')}}</button><button class="secondary danger push" :disabled="busy||!(data.projects.length+data.images.length)" @click="requestPurge()"><Trash2 :size="15"/>{{s.t('清空全部回收内容','Empty recycle bin')}}</button></div><div class="segmented"><button :class="{active:tab==='projects'}" @click="tab='projects'">{{s.t('项目','Projects')}} {{data.projects.length}}</button><button :class="{active:tab==='images'}" @click="tab='images'">{{s.t('图片','Images')}} {{data.images.length}}</button></div><p v-if="error" class="error-note">{{error}}</p><div class="button-row" v-if="data[tab].length"><button class="secondary" :disabled="busy" @click="restoreAll(data[tab])"><RotateCcw :size="15"/>{{s.t('恢复全部','Restore all')}}</button></div><div class="recycle-list"><article v-for="item in data[tab]" :key="item.id"><img v-if="tab==='images'" :src="item.url" alt="" loading="lazy"/><div class="recycle-item-info"><strong>{{item.name||item.title}}</strong><small>{{new Date(item.deletedAt).toLocaleString()}}</small></div><div class="button-row"><button class="secondary" :disabled="busy" @click="restoreAll([item])"><RotateCcw :size="15"/>{{s.t('恢复','Restore')}}</button><button class="quiet danger" :disabled="busy" @click="requestPurge(item)"><Trash2 :size="15"/>{{s.t('永久删除','Delete permanently')}}</button></div></article><p v-if="!data[tab].length" class="empty">{{s.t('回收区为空','The recycle bin is empty')}}</p></div></section><div v-if="confirmation" class="modal-backdrop" @click.self="!busy&&(confirmation=null)"><section class="modal confirm-modal" role="dialog" :aria-label="s.t('确认永久删除','Confirm permanent deletion')"><div class="modal-title"><h2>{{s.t('永久清除回收内容？','Permanently delete recycled content?')}}</h2></div><p>{{s.t('将永久删除以下回收内容：','Permanently delete:')}} {{confirmation.projectIds.length}} {{s.t('个项目','projects')}} · {{confirmation.imageIds.length}} {{s.t('张图片','images')}}</p><p class="error-note">{{s.t('删除后无法恢复。仍被其他项目使用的图片会保留；模型和未删除的作品不会受影响。','This cannot be undone. Images still used by other projects are kept. Models and active creations are unaffected.')}}</p><p v-if="error" class="error-note">{{error}}</p><div class="button-row"><button class="secondary" :disabled="busy" @click="confirmation=null">{{s.t('取消','Cancel')}}</button><button class="primary danger" :disabled="busy" @click="purge"><LoaderCircle v-if="busy" :size="15" class="spin"/><Trash2 v-else :size="15"/>{{s.t('确认永久删除','Delete permanently')}}</button></div></section></div></div></template>
